#include <iostream>
#include <cstring>
using namespace std;

int main() {
    char s[255];
    int n, i;

    cin.getline(s, 255);
    n = strlen(s);

    for (i = 0; i < n; i++) {
        if (i == 0 && s[i] >= 'a' && s[i] <= 'z') {
            s[i] = s[i] - 32;
        } else if (s[i] == ' ' && i + 1 < n) {
            if (s[i+1] >= 'a' && s[i+1] <= 'z') {
                s[i+1] = s[i+1] - 32;
            }
        }
    }

    cout << s;

    return 0;
}

