#include <iostream>
#include <cstring>
using namespace std;

int main() {
    char s1[255], s2[255];
    int n1, n2, i, j, k;
    char sufix[255];

    cin >> s1 >> s2;
    n1 = strlen(s1);
    n2 = strlen(s2);

    i = n1 - 1;
    j = n2 - 1;
    k = 0;

    while (i >= 0 && j >= 0 && s1[i] == s2[j]) {
        i--;
        j--;
        k++;
    }

    if (k == 0) {
        cout << "NU EXISTA";
    } else {
        int start = n1 - k;
        int p;
        for (p = 0; p < k; p++) {
            sufix[p] = s1[start + p];
        }
        sufix[k] = '\0';
        cout << sufix;
    }

    return 0;
}
